<div class="page-heading mb-4"><div><h1>Currency Exchange API</h1><p>Live reference exchange rates supplied by the public Frankfurter REST API.</p></div></div>
<div class="row g-4"><div class="col-lg-4"><div class="card"><div class="card-header">Choose base currency</div><div class="card-body"><form method="get" action="<?= site_url('currency-rates') ?>"><label class="form-label">Base currency</label><select class="form-select mb-3" name="base"><?php foreach(array('INR','USD','EUR','GBP','SGD','AUD') as $c): ?><option <?= $base===$c?'selected':'' ?>><?= $c ?></option><?php endforeach; ?></select><button class="btn btn-primary">Load live rates</button></form><div class="small text-muted mt-3">This section demonstrates integration with an external REST service. Rates are for reference only.</div></div></div></div><div class="col-lg-8"><div class="card"><div class="card-header">Latest rates<?= $rate_date?' · '.html_escape($rate_date):'' ?></div><div class="card-body"><?php if($error): ?><div class="alert alert-warning mb-0"><?= html_escape($error) ?></div><?php elseif($rates): ?><div class="row g-3"><?php foreach($rates as $currency=>$rate): ?><div class="col-sm-6 col-xl-4"><div class="rate-card"><div class="small text-muted">1 <?= html_escape($base) ?> equals</div><div class="fs-4 fw-bold"><?= number_format((float)$rate,4) ?></div><div class="fw-semibold"><?= html_escape($currency) ?></div></div></div><?php endforeach; ?></div><?php endif; ?></div></div></div></div>
